INSERT INTO archetypes (id, locale, name, summary, motto, ordinal) VALUES
  ('quiet_builder', 'tr', 'Sessiz İnşacı', 'Gürültü çıkarmadan biriktirirsin; kimse ilk taşı görmez, herkes duvarı görür. Bedeli şu: görünmediğin için çoğu zaman hakkın da teslim edilmez.', 'Acele etmeyen ama durmayan.', 1),
  ('spark', 'tr', 'Kıvılcım', 'Bir sürü şeye başlarsın ve sorun ilgisizlik değil — hepsinin gerçekten iyi fikir olması. Zor olan tutuşturmak değil, birini seçmek.', 'Bugün sadece bir tanesi.', 2),
  ('night_watch', 'tr', 'Gece Nöbetçisi', 'Sen fark ettiğinde iş henüz olmamıştır. Herkes rahatken senin çoktan düşünmüş olman yorucu, ama defalarca işe yaradı.', 'Tetikte olmak da bir güç, dinlenmek de.', 3),
  ('table_setter', 'tr', 'Sofra Kuran', 'İnsanları bir araya getiren sensin ve bunu kimse senden istemiyor bile. Herkesin iyi hissetmesini o kadar önemsiyorsun ki, sıra sana geldiğinde masada yer kalmıyor.', 'Onlardan önce bir de bana sor.', 4),
  ('fine_worker', 'tr', 'İnce İşçi', '"Olur böyle" cümlesi sende çalışmıyor; farkı kimsenin görmediği yerde de görüyorsun. Bitirmeni zorlaştıran şey tembellik değil, standardın.', 'Mükemmel değil, bitmiş olsun.', 5),
  ('compass', 'tr', 'Yön Veren', 'Kimse karar vermeyince sen veriyorsun ve genelde doğru çıkıyor. Bedeli: herkesin katılmasını beklemediğin için bazen yalnız yürüyorsun.', 'Karar vermek de bir yük, taşıyorum.', 6),
  ('still_water', 'tr', 'Durgun Su', 'Herkes telaşlanırken sen sakin kalıyorsun ve bu, etrafındakileri de sakinleştiriyor. Ama o kadar sorun etmiyorsun ki, gerçekten sorun olan şey de gecikiyor.', 'Sakinim, kayıtsız değil.', 7),
  ('deep_diver', 'tr', 'Derin Dalgıç', 'Her şeyi bir kat daha derinden yaşıyorsun; iyisini de kötüsünü de. Yüzeyde kalabilseydin rahat ederdin ama o zaman sen olmazdın.', 'Derinde kalmak değil, dalıp çıkmak.', 8),
  ('own_clock', 'tr', 'Kendi Saatinde', 'Sistemle değil, dalgayla çalışıyorsun; geldiğinde tamamen geliyor. Bedeli şu: hiçbir şey birikmiyor, ve kimse sana göre plan yapamıyor — sen de dahil.', 'Kendi saatimde ama her gün.', 9),
  ('contrarian', 'tr', 'Aykırı', 'Ne düzenmiş gibi yapıyorsun ne de katılıyormuş gibi, o yüzden senden duyduğun şey gerçek olan. Bedeli şu: sonradan ihtiyacın olacak iyi niyeti bugün harcıyorsun.', 'Karşı çıkmak kolay, sürdürmek zor.', 10),
  ('feet_on_ground', 'tr', 'Ayağı Yerde', 'Bugünün işine bakıyorsun ve elindekiyle çözüyorsun; teoriye de plana da ihtiyacın olmuyor. Bedeli şu: hiçbir şey değişmiyor, çünkü değişim ya merak ister ya plan, ikisini de taşımıyorsun.', 'Bugün elimde olanla.', 11),
  ('as_is', 'tr', 'Olduğu Gibi', 'Ne yakınlık için uğraşıyorsun ne de araları düzeltmek için; seni tanıyan, tam olarak seni tanıyor. Bedeli şu: bir süre sonra kimse sormuyor, ve bunu ancak bir şeye ihtiyacın olduğunda fark ediyorsun.', 'Az kişiye açık, onlara tamamen.', 12),
  ('table_upsetter', 'tr', 'Masayı Deviren', 'Odada kimsenin söylemediği şeyi sen söylüyorsun ve genelde söylenmesi gerekiyordu. Bedeli şu: söyledikten sonra orada kalman gerekiyor, ve kalmak söylemekten çok daha zor.', 'Söylemesi kolaydı, kalması değil.', 13),
  ('light_footed', 'tr', 'Hafif Ayaklı', 'Kalabalık da aksilik de seni yormuyor; ikisinin içinden aynı rahatlıkla geçiyorsun. Bedeli şu: hiçbir şeyi büyütmediğin için gerçekten büyük olanı da geç fark ediyorsun.', 'Taşımadan da gidilir, ama bunu değil.', 14),
  ('full_glass', 'tr', 'Dolu Bardak', 'Her şeyi aynı anda ve tamamen hissediyorsun, o yüzden zor olan ne yapacağın değil neyi önce yapacağın. Bedeli şu: taşmamak için harcadığın enerjiyi işin kendisine ayıramıyorsun.', 'Bir yudum boşalt, sonra taşı.', 15),
  ('word_is_bond', 'tr', 'Sözü Senet', 'Söylediğin şey oluyor ve insanlar bunu sen söylemeden önce biliyorlar. Bedeli şu: kimse senden "yapamam" duymadığı için sormaya da devam ediyor, ve sıra kendi işine en son geliyor.', 'Söz verdiğim kadarı, o kadarı da tam.', 16),
  ('in_its_place', 'tr', 'Yerli Yerinde', 'Denenmiş olanı denenmiş olduğu için seçiyorsun ve bu seni sarsılmaz yapıyor; etrafındakiler de bunu bilerek plan yapıyor. Bedeli şu: değişmesi gereken şey de aynı yerde duruyor, çünkü onu da yerinde sanıyorsun.', 'Yerinde duranı da bir yokla.', 17),
  ('inwardly', 'tr', 'İçten İçe', 'Kimseye söylemeden çok şey taşıyorsun; birinin canı sıkkınsa sen zaten fark etmişsindir. Bedeli şu: fark ettiğini söylemediğin için yardım hep tek yönlü akıyor, ve bir gün sana lazım olduğunda kimsenin aklına gelmiyorsun.', 'Ben de söyleyebilirim.', 18);
